def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_State_Rankings_Identity_Theft_Reports.csv'
    # Try common encodings used in these FTC CSN exports
    for enc in ['utf-8', 'utf-8-sig', 'cp1252', 'latin1']:
        try:
            return pd.read_csv(path, encoding=enc)
        except UnicodeDecodeError:
            continue
    # Fallback: replace undecodable chars
    return pd.read_csv(path, encoding='utf-8', errors='replace')

def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_State_Rankings_Fraud_and_Other_Reports.csv'
    for enc in ['utf-8','utf-8-sig','cp1252','latin1']:
        try:
            return pd.read_csv(path, encoding=enc)
        except Exception:
            continue
    return pd.read_csv(path, encoding_errors='ignore')

def load() -> pd.DataFrame:
    import pandas as pd, glob, os
    files = sorted(glob.glob('data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*.csv'))
    return pd.DataFrame({'path': files, 'file': [os.path.basename(f) for f in files]})
